/* Seed screening tool questions (from question bank) — safe to re-run */
IF NOT EXISTS (SELECT 1 FROM [dbo].[CMS_ScreeningToolQuestions] WHERE [ToolCode]=N'PHQ9')
BEGIN
    UPDATE [dbo].[CMS_ScreeningTools] SET [SortOrder]=1 WHERE [ToolCode]=N'PHQ9';
    INSERT INTO [dbo].[CMS_ScreeningToolQuestions] ([ToolCode], [QuestionText], [SortOrder], [OptionsJson])
    SELECT N'PHQ9', JSON_VALUE(value, '$.text'), ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, JSON_QUERY(value, '$.options')
    FROM OPENJSON(N'[{"text":"Little interest or pleasure in doing things","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Feeling down, depressed, or hopeless","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Trouble falling or staying asleep, or sleeping too much","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Feeling tired or having little energy","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Poor appetite or overeating","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Feeling bad about yourself — or that you are a failure or have let yourself or your family down","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Trouble concentrating on things, such as reading the newspaper or watching television","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Moving or speaking so slowly that other people could have noticed — or the opposite, being so fidgety or restless that you have been moving around a lot more than usual","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Thoughts that you would be better off dead, or of hurting yourself in some way","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]}]');
END
IF NOT EXISTS (SELECT 1 FROM [dbo].[CMS_ScreeningToolQuestions] WHERE [ToolCode]=N'GAD7')
BEGIN
    UPDATE [dbo].[CMS_ScreeningTools] SET [SortOrder]=2 WHERE [ToolCode]=N'GAD7';
    INSERT INTO [dbo].[CMS_ScreeningToolQuestions] ([ToolCode], [QuestionText], [SortOrder], [OptionsJson])
    SELECT N'GAD7', JSON_VALUE(value, '$.text'), ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, JSON_QUERY(value, '$.options')
    FROM OPENJSON(N'[{"text":"Feeling nervous, anxious, or on edge","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Not being able to stop or control worrying","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Worrying too much about different things","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Trouble relaxing","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Being so restless that it is hard to sit still","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Becoming easily annoyed or irritable","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]},{"text":"Feeling afraid as if something awful might happen","options":[{"t":"Not at all","v":0},{"t":"Several days","v":1},{"t":"More than half the days","v":2},{"t":"Nearly every day","v":3}]}]');
