IF NOT EXISTS (SELECT 1 FROM [dbo].[CMS_ScreeningToolQuestions] WHERE [ToolCode]=N'DASS21')
BEGIN
    UPDATE [dbo].[CMS_ScreeningTools] SET [SortOrder]=3 WHERE [ToolCode]=N'DASS21';
    INSERT INTO [dbo].[CMS_ScreeningToolQuestions] ([ToolCode], [QuestionText], [SortOrder], [OptionsJson])
    SELECT N'DASS21', JSON_VALUE(value, '$.text'), ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, JSON_QUERY(value, '$.options')
    FROM OPENJSON(N'[{"text":"I found it hard to wind down","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I was aware of dryness of my mouth","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I couldn''t seem to experience any positive feeling at all","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I experienced breathing difficulty (e.g. excessively rapid breathing, breathlessness in the absence of physical exertion)","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I found it difficult to work up the initiative to do things","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I tended to over-react to situations","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I experienced trembling (e.g. in the hands)","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I felt that I was using a lot of nervous energy","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I was worried about situations in which I might panic and make a fool of myself","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I felt that I had nothing to look forward to","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I found myself getting agitated","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I found it difficult to relax","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I felt down-hearted and blue","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I was intolerant of anything that kept me from getting on with what I was doing","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I felt I was close to panic","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I was unable to become enthusiastic about anything","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I felt I wasn''t worth much as a person","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I felt that I was rather touchy","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I was aware of the action of my heart in the absence of physical exertion (e.g. sense of heart rate increase, heart missing a beat)","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I felt scared without any good reason","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]},{"text":"I felt that life was meaningless","options":[{"t":"Did not apply to me at all","v":0},{"t":"Applied to me to some degree, or some of the time","v":1},{"t":"Applied to me to a considerable degree, or a good part of time","v":2},{"t":"Applied to me very much, or most of the time","v":3}]}]');
END
IF NOT EXISTS (SELECT 1 FROM [dbo].[CMS_ScreeningToolQuestions] WHERE [ToolCode]=N'SBQR')
BEGIN
    UPDATE [dbo].[CMS_ScreeningTools] SET [SortOrder]=4 WHERE [ToolCode]=N'SBQR';
    INSERT INTO [dbo].[CMS_ScreeningToolQuestions] ([ToolCode], [QuestionText], [SortOrder], [OptionsJson])
    SELECT N'SBQR', JSON_VALUE(value, '$.text'), ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, JSON_QUERY(value, '$.options')
    FROM OPENJSON(N'[{"text":"Have you ever thought about or attempted to kill yourself?","options":[{"t":"Never","v":1},{"t":"It was just a brief passing thought","v":2},{"t":"I have had a plan at least once to kill myself but did not try to do it or work it out","v":3},{"t":"I have attempted to kill myself, but did not want to die","v":4},{"t":"I have attempted to kill myself, and really hoped to die","v":4}]},{"text":"How often have you thought about killing yourself in the past year?","options":[{"t":"Never","v":1},{"t":"Rarely (1 time)","v":2},{"t":"Sometimes (2 times)","v":3},{"t":"Often (3–4 times)","v":4},{"t":"Very often (5 or more times)","v":5}]},{"text":"Have you ever told someone that you were going to commit suicide, or that you might do it?","options":[{"t":"No","v":1},{"t":"Yes, at one time, but did not really want to die","v":2},{"t":"Yes, at one time, and really wanted to die","v":3},{"t":"Yes, more than once, and really wanted to do it","v":3}]},{"text":"How likely is it that you will attempt suicide someday?","options":[{"t":"Never","v":0},{"t":"No chance at all","v":1},{"t":"Rather unlikely","v":2},{"t":"Unlikely","v":3},{"t":"Likely","v":4},{"t":"Rather likely","v":5},{"t":"Very likely","v":6}]}]');
END
IF NOT EXISTS (SELECT 1 FROM [dbo].[CMS_ScreeningToolQuestions] WHERE [ToolCode]=N'CSSRS')
BEGIN
    UPDATE [dbo].[CMS_ScreeningTools] SET [SortOrder]=5 WHERE [ToolCode]=N'CSSRS';
    INSERT INTO [dbo].[CMS_ScreeningToolQuestions] ([ToolCode], [QuestionText], [SortOrder], [OptionsJson])
    SELECT N'CSSRS', JSON_VALUE(value, '$.text'), ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, JSON_QUERY(value, '$.options')
    FROM OPENJSON(N'[{"text":"Have you wished you were dead or wished you could go to sleep and not wake up?","options":[{"t":"No","v":0},{"t":"Yes","v":1}]},{"text":"Have you actually had any thoughts of killing yourself?","options":[{"t":"No","v":0},{"t":"Yes","v":1}]},{"text":"Have you been thinking about how you might do this?","options":[{"t":"No","v":0},{"t":"Yes","v":1}]},{"text":"Have you had these thoughts and had some intention of acting on them?","options":[{"t":"No","v":0},{"t":"Yes","v":1}]},{"text":"Have you started to work out or worked out the details of how to kill yourself? Do you intend to carry out this plan?","options":[{"t":"No","v":0},{"t":"Yes","v":1}]},{"text":"Have you done anything, started to do anything, or prepared to do anything to end your life?","options":[{"t":"No","v":0},{"t":"Yes","v":1}]}]');
END
